  'navigation.ourMissionDescription': 'Unsere Mission ist es, Web2 und Web3 zu vereinen und Blockchain-Technologie für alle zugänglich und benutzerfreundlich zu machen. Wir setzen uns dafür ein, sichere, intuitive und leistungsstarke Werkzeuge bereitzustellen, die es den Nutzern ermöglichen, die volle Kontrolle über ihre digitalen Vermögenswerte zu übernehmen.',
