  'navigation.passKeyDesc1': 'Erleben Sie nahtlose Wallet-Sicherheit mit PassKey-Technologie. Entsperren Sie Ihre Wallet sofort mittels PassKey-Authentifizierung (biometrisch, Face ID oder Geräte-PIN), anstatt Passwörter einzugeben.',
  'navigation.passKeyDesc2': 'Aktivieren Sie die automatische Passwort-Autovervollständigung für Transaktionssignaturen, damit Sie Ihr Ausgabepasswort nicht jedes Mal eingeben müssen. Konfigurieren Sie PassKey-Einstellungen unabhängig für Wallet-Entsperrung und das automatische Ausfüllen von Transaktionen in den Sicherheitseinstellungen.',
