  // Shielded-Proving-Consent-Dialog
  'midnight.consent.title': 'Privatsphäre beim Shielded-Senden',
  'midnight.consent.subtitle': 'Vor deiner ersten Shielded-Transaktion',
  'midnight.consent.intro': 'Zum Senden von Shielded-NIGHT muss die Wallet beweisen, dass die Transaktion gültig ist, ohne deine Notes preiszugeben. Für diesen Beweis werden die Witness-Daten innerhalb der Transaktion benötigt.',
  'midnight.consent.whatGeroSees': 'Was Gero Cloud sieht',
  'midnight.consent.whatGeroSeesBody': 'Bei jedem Shielded-Send empfängt unser Proving-Server kurzzeitig die Witness-Daten und erstellt damit einen Zero-Knowledge-Beweis. Wer den Request-Body dieses Sendens lesen kann, kann die ausgegebenen Notes mit dieser Transaktion verknüpfen.',
  'midnight.consent.whatWeDoNot': 'Was wir nicht tun',
  'midnight.consent.whatWeDoNotBody': 'Wir loggen oder speichern die Witness-Daten nicht. Wir verknüpfen sie nicht mit deinem Konto, deiner IP oder einem anderen Identifier, der nicht im Request selbst enthalten ist.',
  'midnight.consent.localOption': 'Möchtest du deinen eigenen Proof-Server betreiben?',
  'midnight.consent.localOptionBody': 'Betreibe den offiziellen Midnight-Proof-Server auf deinem eigenen Rechner und Gero erstellt Beweise lokal. Deine privaten Transaktionsdaten verlassen deinen Computer nie. Einrichtung unter Einstellungen.',
  'midnight.consent.acknowledge': 'Ich verstehe, dass Geros Server die Witness-Daten jeder Shielded-Transaktion sehen, die ich sende, und dass jeder, der sie liest, meine Shielded-Notes mit diesen Sends verknüpfen kann.',
  'midnight.consent.acceptCloud': 'Gero Cloud nutzen',
  'midnight.consent.useLocalInstead': 'Stattdessen lokalen Proof-Server nutzen',
  'midnight.consent.cancel': 'Abbrechen',
  // Arkhia-zkPaaS-Variante derselben Einwilligung (die Witness-Daten gehen
  // an Arkhia, nicht an Gero, also muss der Text das echte Ziel nennen)
  'midnight.consent.zkpaasWhatSees': 'Was Arkhia zkPaaS sieht',
  'midnight.consent.zkpaasWhatSeesBody': 'Bei jedem Shielded-Send empfängt Arkhias zkPaaS-Dienst kurzzeitig die Witness-Daten und erstellt damit einen Zero-Knowledge-Beweis. Geros Server erhalten sie auf diesem Weg nie. Wer den Request-Body dieses Sendens lesen kann, kann die ausgegebenen Notes mit dieser Transaktion verknüpfen.',
  'midnight.consent.zkpaasWhatThisMeans': 'Was das bedeutet',
  'midnight.consent.zkpaasWhatThisMeansBody': 'Arkhia betreibt den Prover auf vertraulicher Google-Cloud-Hardware und erklärt, Witness-Daten nicht zu speichern. Gero kann das nicht für jede Anfrage überprüfen; behandle den Dienst daher wie jeden anderen entfernten Prover.',
  'midnight.consent.zkpaasAcknowledge': 'Ich verstehe, dass Arkhias Server die Witness-Daten jeder Shielded-Transaktion sehen, die ich sende, und dass jeder, der sie liest, meine Shielded-Notes mit diesen Sends verknüpfen kann.',
  'midnight.consent.zkpaasAccept': 'Arkhia zkPaaS nutzen',
